/* TRX-B2 44.1 kHz render (trxb2_render_block_44k1), hand-written SHARC+.
 * Generated by gen_trxb2.py.
 *
 * Bit-exact replacement for the translated render of the original OS 1.63
 * DSP56300 code at P:$102c5a-$102d05 (model: trxb2_model.py). It keeps the
 * translated voice layout and the shared scratch contract: every word of
 * voice state, x/y scratch, y:$20 history and the 44.1 kHz block ends as
 * the original leaves it.
 *
 *  1. Phase phi = (phi + Y1 + e) & $7fffff, e = lim(2*Yd*e) (Y19, Ye) into
 *     x:$40+k.
 *  2. Quadrant sine: q = phi >> 21, p = phi - sub(q); with p' = -|p| the
 *     original's index b1 is min(floor(2*Y(5+q)*p'), $1fff) for even q and
 *     max(.., -$1fff) for odd q, plus $4000 * (q + 1) / 2; the word at
 *     x:($148000 + index) under the $8000-word modulo window (one wrap;
 *     outside the sine table: a memory fault and 0) into x:k. Per-quadrant
 *     constants in an @TMP@ table.
 *  3. Bit reduction: x:$40+k = lim((x:k + Ya) & (-1 << (Y9 & 63))).
 *  4. Sparse Fibonacci noise (Y13, Y14) into x:$20+4j.
 *  5. Envelope x1 = lim(2*x1*x0 + a) (a = Y10 until the sum reaches 1/2,
 *     x0 = $7ffff8 or Y3 by Y18) times x:$40+k; block = x:$40+k +
 *     8 * 2*c*0.9 + 2*Y11*noise, c = Y17 decaying by 0.9.
 *
 * Declines (calls the reference render) when a slope |Y5..Y8| > $47ffff
 * (which keeps every index above the boot X words).
 *
 * Calling convention as the translated renders: R4 = voice, R8 = sine.
 * @SRC@ = byte address of source word 0 (immutable source base - 0x80000).
 * @TMP@ = a 256-word scratch block owned by the hand-written renders.
 */
.EXTERN md_shared_scratch_x.;
.EXTERN md_shared_scratch_y.;
.EXTERN md_shared_y20.;
.EXTERN trxb2_render_block_44k1_c.;
.SECTION/SW seg_swco;
.GLOBAL trxb2_render_block_44k1.;
trxb2_render_block_44k1.:
    I7=MODIFY (I7,-0x34)(NW);
    DM (-3,I6) = R8;
    DM (-4,I6) = R9;
    DM (-5,I6) = R10;
    DM (-6,I6) = R11;
    DM (-7,I6) = R12;
    DM (-8,I6) = R13;
    DM (-9,I6) = R14;
    DM (-10,I6) = R15;
    R0 = I0;
    DM (-11,I6) = R0;
    R0 = I1;
    DM (-12,I6) = R0;
    R0 = I2;
    DM (-13,I6) = R0;
    R0 = I3;
    DM (-14,I6) = R0;
    R0 = I4;
    DM (-15,I6) = R0;
    R0 = I5;
    DM (-16,I6) = R0;
    R0 = M4;
    DM (-17,I6) = R0;
    R0 = M0;
    DM (-18,I6) = R0;
    R0 = M1;
    DM (-19,I6) = R0;
    R0 = M2;
    DM (-20,I6) = R0;
    R0 = M3;
    DM (-21,I6) = R0;
    R0 = MR0F;
    DM (-22,I6) = R0;
    R0 = MR1F;
    DM (-23,I6) = R0;
    R0 = MR2F;
    DM (-24,I6) = R0;
    DM (-28,I6) = R8;
    R0 = L0;
    DM (-46,I6) = R0;
    R0 = L1;
    DM (-47,I6) = R0;
    R0 = L2;
    DM (-48,I6) = R0;
    R0 = L3;
    DM (-49,I6) = R0;
    R0 = L4;
    DM (-50,I6) = R0;
    R0 = L5;
    DM (-51,I6) = R0;
    R0 = 0;
    L0 = R0;
    L1 = R0;
    L2 = R0;
    L3 = R0;
    L4 = R0;
    L5 = R0;
    I0 = R4;
    R14 = 0x7FFFFF;
    R15 = 0xFF800000;
    R13 = @SRC@;
/* ---- guards: nothing is written before these pass ---------------------- */
    R1 = 0x47FFFF;
    R0 = DM (5,I0);
    R0 = ABS R0;
    COMP (R0,R1);
    IF GT JUMP .L_decline;
    R0 = DM (6,I0);
    R0 = ABS R0;
    COMP (R0,R1);
    IF GT JUMP .L_decline;
    R0 = DM (7,I0);
    R0 = ABS R0;
    COMP (R0,R1);
    IF GT JUMP .L_decline;
    R0 = DM (8,I0);
    R0 = ABS R0;
    COMP (R0,R1);
    IF GT JUMP .L_decline;
    /* y:$20 history: y:$20 = y20 at entry, y20 = u24(y:$20) at exit */
    I1 = md_shared_y20.;
    R1 = DM (0,I1);
    R1 = FEXT R1 BY 0:24;
    DM (0,I1) = R1;
    R1 = LSHIFT R1 BY 8;
    R6 = -8;
    R1 = ASHIFT R1 BY R6;
    I1 = md_shared_scratch_y.;
    DM (32,I1) = R1;
/* ---- 1. phase into x:$40+k -------------------------------------------- */
    R1 = DM (0xE,I0);                   /* e */
    R2 = DM (0xD,I0);
    R2 = LSHIFT R2 BY 8;
    R3 = DM (1,I0);
    R4 = DM (0x19,I0);
    R4 = FEXT R4 BY 0:24;               /* phi */
    R5 = 0x7FFFFF;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x40)(NW);
    LCNTR = 0x20 , DO (PC,.L_phase_end)UNTIL LCE;
    R1 = R1 * R2 (SSF);
    R1 = MIN(R1,R14);
    R4 = R4 + R3;
    R4 = R4 + R1;
    R4 = R4 AND R5;
.L_phase_end:
    DM (I1,M6) = R4;
    DM (0xE,I0) = R1;
    DM (0x19,I0) = R4;
.L_s2:
/* ---- quadrant table: sub, slope, add, upper, lower -------------------- */
    I2 = @TMP@;
    I2=MODIFY (I2,0x20)(NW);
    R0 = 0x0;
    DM (0,I2) = R0;
    R0 = DM (5,I0);
    DM (1,I2) = R0;
    R0 = 0x0;
    DM (2,I2) = R0;
    R0 = 8191;
    DM (3,I2) = R0;
    R0 = -2147483647;
    DM (4,I2) = R0;
    R0 = 0x400000;
    DM (8,I2) = R0;
    R0 = DM (6,I0);
    DM (9,I2) = R0;
    R0 = 0x4000;
    DM (10,I2) = R0;
    R0 = 2147483647;
    DM (11,I2) = R0;
    R0 = -8191;
    DM (12,I2) = R0;
    R0 = 0x400000;
    DM (16,I2) = R0;
    R0 = DM (7,I0);
    DM (17,I2) = R0;
    R0 = 0x4000;
    DM (18,I2) = R0;
    R0 = 8191;
    DM (19,I2) = R0;
    R0 = -2147483647;
    DM (20,I2) = R0;
    R0 = 0x800000;
    DM (24,I2) = R0;
    R0 = DM (8,I0);
    DM (25,I2) = R0;
    R0 = 0x8000;
    DM (26,I2) = R0;
    R0 = 2147483647;
    DM (27,I2) = R0;
    R0 = -8191;
    DM (28,I2) = R0;

/* ---- 2./3. quadrant sine into x:k, bit reduction into x:$40+k ------------- */
    R0 = DM (-28,I6);
    I4 = R0;                            /* sine table */
    R8 = -21;
    R9 = -8;
    R10 = 0x8000;
    R11 = DM (0xA,I0);                  /* Ya */
    R0 = DM (9,I0);
    R1 = 63;
    R0 = R0 AND R1;
    R12 = -1;
    R12 = LSHIFT R12 BY R0;             /* bit mask (0 for 32 and up) */
    R3 = I2;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x40)(NW);
    I5 = md_shared_scratch_x.;
    LCNTR = 0x20 , DO (PC,.L_sine_end)UNTIL LCE;
    R5 = DM (I1,M5);                    /* phi */
    R0 = LSHIFT R5 BY R8;               /* q */
    R0 = LSHIFT R0 BY 5;
    R0 = R0 + R3;
    I3 = R0;                            /* quadrant table row */
    R2 = DM (0,I3);
    R1 = DM (1,I3);
    R6 = R5 - R2;
    R6 = ABS R6;
    R6 = -R6;
    R6 = LSHIFT R6 BY 8;
    R6 = R6 * R1 (SSF) , R2 = DM (3,I3);
    R6 = MIN(R6,R2) , R2 = DM (4,I3);
    R6 = MAX(R6,R2) , R2 = DM (2,I3);
    R6 = R6 + R2;                       /* index */
    COMPU (R6,R10);
    IF LT JUMP .L_sine_near;
    /* (inlined .L_far) */
    R0 = PASS R6;
    IF LT JUMP .L_far_neg_i1;
    R0 = R0 - R10;
    JUMP .L_far_chk_i1;
.L_far_neg_i1:
    R0 = R0 + R10;
.L_far_chk_i1:
    COMPU (R0,R10);
    IF GE JUMP .L_far_src_i1;
    M4 = R0;
    JUMP .L_far_ret_i1 (DB);
    R7 = DM (M4,I4);
    NOP;
.L_far_src_i1:
    R0 = 1;
    DM (0x46,I0) = R0;                  /* memory fault (outside the sine table) */
    JUMP .L_far_ret_i1 (DB);
    R7 = 0;
    NOP;
.L_far_ret_i1:
    JUMP .L_sine_got;
.L_sine_near:
    M4 = R6;
    R7 = DM (M4,I4);
.L_sine_got:
    R7 = LSHIFT R7 BY 8;
    R7 = ASHIFT R7 BY R9;
    R7 = R7 + R11 , DM (I5,M6) = R7;
    R7 = R7 AND R12;
    R7 = MIN(R7,R14);
    R7 = MAX(R7,R15);
.L_sine_end:
    DM (I1,M6) = R7;
    JUMP .L_noise;

    /* index R6 outside [0, $8000): one modulo wrap, then R7 = the word at
     * x:($148000 + offset): the sine table, or (TRX-B2 maps nothing else
     * there; the slope guard keeps the address in $30000-$268000) a memory
     * fault and 0 */

/* ---- 4. sparse noise: x:$20+4j = f(j+1), x:$21..$23+4j = 0 ---------------- */
.L_noise:
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x20)(NW);
    R1 = DM (0x13,I0);
    R1 = LSHIFT R1 BY 8;
    R2 = DM (0x14,I0);
    R2 = LSHIFT R2 BY 8;
    R3 = 0;
    R6 = -8;
    LCNTR = 4 , DO (PC,.L_nz_end)UNTIL LCE;
    R1 = R1 + R2;
    R0 = ASHIFT R1 BY R6;
    DM (I1,M6) = R0;
    DM (I1,M6) = R3;
    DM (I1,M6) = R3;
    DM (I1,M6) = R3;
    R2 = R2 + R1;
    R0 = ASHIFT R2 BY R6;
    DM (I1,M6) = R0;
    DM (I1,M6) = R3;
    DM (I1,M6) = R3;
.L_nz_end:
    DM (I1,M6) = R3;
    R1 = ASHIFT R1 BY R6;
    DM (0x13,I0) = R1;
    R2 = ASHIFT R2 BY R6;
    DM (0x14,I0) = R2;
/* ---- Y11 = lim(2*Y11*Y12); Y18 = lim(2*Y4*Y18); decay x0 ---------------- */
    R0 = DM (0x11,I0);
    R1 = DM (0x12,I0);
    R1 = LSHIFT R1 BY 8;
    R0 = R0 * R1 (SSF);
    R0 = MIN(R0,R14);
    DM (0x11,I0) = R0;
    R7 = LSHIFT R0 BY 8;                /* Y11 << 8 */
    R0 = DM (0x18,I0);
    R1 = DM (4,I0);
    R1 = LSHIFT R1 BY 8;
    R0 = R0 * R1 (SSF);
    R0 = MIN(R0,R14);
    DM (0x18,I0) = R0;
    R2 = 0x7FFFF8;
    R1 = 0x147AE;
    COMP (R0,R1);
    R3 = DM (3,I0);
    IF LT R2 = PASS R3;
    R2 = LSHIFT R2 BY 8;                /* x0 << 8 */

/* ---- 5. envelope and block ------------------------------------------------ */
    R1 = DM (0x15,I0);                  /* x1 */
    R3 = DM (0x10,I0);                  /* a */
    R4 = 0x400000;
    R5 = DM (0x17,I0);                  /* c */
    R6 = 0x73333300;
    R12 = 3;
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x40)(NW);
    I2 = md_shared_scratch_x.;
    I2=MODIFY (I2,0x20)(NW);
    R0 = 0x68;
    R9 = I0;
    R0 = R0 + R9;
    I4 = R0;
    LCNTR = 0x20 , DO (PC,.L_env_end)UNTIL LCE;
    R9 = R1 * R2 (SSF) , R0 = DM (I1,M5);
    R9 = R9 + R3;
    COMP (R9,R4);
    IF GE R3 = R3 - R3;
    R1 = MIN(R9,R14);
    R1 = MAX(R1,R15);
    R10 = LSHIFT R1 BY 8;
    R0 = R0 * R10 (SSF);
    R0 = MIN(R0,R14);
    DM (I1,M6) = R0;
    R9 = LSHIFT R5 BY R12;
    R10 = R6 * R9 (SSI) , R11 = DM (I2,M6);
    R9 = R6 * R9 (SSF);
    R10 = R10 + R10;                    /* low word of 8 * 2*c*0.9 */
    R9 = R9 + R0;                       /* + x:$40+k at MR1 */
    MR1F = R9;
    MR0F = R10;
    MRF = MRF + R7 * R11 (SSF);         /* + 2*Y11*noise */
    R5 = R6 * R5 (SSF);
    R9 = MR1F;
    R9 = MIN(R9,R14);
    R9 = MAX(R9,R15);
.L_env_end:
    DM (I4,M6) = R9;
    DM (0x15,I0) = R1;
    R3 = MIN(R3,R14);
    R3 = MAX(R3,R15);
    DM (0x10,I0) = R3;
    DM (0x17,I0) = R5;
    JUMP .L_exit;
.L_decline:
    /* tail call: the C reference render runs in this render's place, in
     * its caller's frame (not nested under this one: the audio stack is
     * 509 words) */
    R4 = I0;
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I7=MODIFY (I7,0x34)(NW);
    JUMP trxb2_render_block_44k1_c.;
.L_exit:
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I12=DM (M7,I6);
    JUMP (M14,I12) (DB);
    RFRAME;
